sys_script_include.script:
// This Script is used to sync the device details between the Sixscape and the IDCentral
var ScheduleForDeviceSync = Class.create();
ScheduleForDeviceSync.prototype = {
    _cachedToken: null,
    _cachedExpiry: 0,

    syncDevices: function() {
        try {
            var authToken = this._getValidAuthToken();
            var existingDeviceIds = this._getExistingDeviceIds();
            var profileGroupIds = this._getProfileGroupIds();
            var endpoint = this._getCleanEndpoint();
            var midServer = gs.getProperty("x_1784056_sixscape.Mid Server Name");

            profileGroupIds.forEach(function(groupId) {
				this._log("Info", "Processing profile group: " + groupId);
                var profileSysId = this._getProfileSysIdByGroupId(groupId);
                if (!profileSysId) {
					this._log("Warning", "No profile found for group id: " + groupId);
                    return;
                }

                authToken = this._getValidAuthToken();
                var restMessage = this._createRestMessage(midServer);

                var deviceOwnerIds = this._fetchDevicesByOwner(restMessage, authToken, endpoint, groupId, profileSysId, existingDeviceIds);

                // Defensive: **skip batch processing if we get no ownerIds**
                if (!deviceOwnerIds || deviceOwnerIds.length === 0) {
					this._log("Warning", "No deviceOwnerIds found for group: " + groupId + ". Skipping batch.");
                    return;
                }

                authToken = this._getValidAuthToken();
                restMessage = this._createRestMessage(midServer);

                this._processDevicesInBatches(restMessage, authToken, endpoint, deviceOwnerIds, profileSysId, existingDeviceIds);

            }.bind(this));

            this._deleteObsoleteDevices(existingDeviceIds);
			this._log("Info", "Device sync completed.");

            authToken = this._getValidAuthToken();
            this._updateCertificatesForDevices(authToken, endpoint);

        } catch (ex) {
            this._logError("top-level", "exception", "", "", ex.message);
            throw ex;
        }
    },

    _getValidAuthToken: function() {
        var now = Math.floor(new Date().getTime() / 1000);
        if (this._cachedToken && this._cachedExpiry > now + 60) {
            return this._cachedToken;
        }
        var tokenObj = new GetToken();
        var response = tokenObj.TestConnection();
        if (!Array.isArray(response) || response.length < 2) {
            this._logError("auth", "getToken", "", "", "Invalid response: " + JSON.stringify(response));
            throw new Error('Invalid response from Token API.');
        }
        var status = response[0];
        var responseBody = response[1];
        if (status !== 200) {
            this._logError("auth", "getToken", "", "", "Token API returned status: " + status);
            throw new Error('Token API returned status: ' + status);
        }
        var parsed = JSON.parse(responseBody);
        var rawToken = parsed.authToken;
        if (!rawToken) {
            this._logError("auth", "getToken", "", "", "Token response missing authToken");
            throw new Error('Token response missing authToken');
        }
        this._cachedToken = 'Bearer ' + rawToken;
        this._cachedExpiry = this._getExpiryFromJwt(rawToken);
        if (!this._cachedExpiry) {
            this._logError("auth", "getToken", "", "", "Failed to parse expiry from token");
            throw new Error('Failed to parse expiry from token');
        }
        return this._cachedToken;
    },

    _getExpiryFromJwt: function(token) {
        var parts = token.split('.');
        if (parts.length !== 3) return null;
        var payloadBase64 = parts[1];
        var payloadJson = this._base64UrlDecode(payloadBase64);
        if (!payloadJson) return null;
        try {
            var payload = JSON.parse(payloadJson);
            return payload.exp || null;
        } catch (e) {
            return null;
        }
    },

    _base64UrlDecode: function(str) {
        str = str.replace(/-/g, '+').replace(/_/g, '/');
        while (str.length % 4) {
            str += '=';
        }
        try {
            return gs.base64Decode(str);
        } catch (e) {
            this._logError("internal", "base64decode", "", str, "Base64 decode error: " + e.message);
            return null;
        }
    },

    _getExistingDeviceIds: function() {
        var deviceIds = [];
        var gr = new GlideRecordSecure('x_1784056_sixscape_device');
        gr.addQuery("device_name", "NOT LIKE", "Add New Application");
        gr.query();
        while (gr.next()) {
            deviceIds.push(gr.getValue('device_id'));
        }
        return deviceIds;
    },

    _getProfileGroupIds: function() {
        var groupIds = [];
        var gr = new GlideRecordSecure('x_1784056_sixscape_profile');
        gr.query();
        while (gr.next()) {
            var groupId = gr.getValue('profile_group_id');
            if (groupId) {
                groupIds.push(groupId);
            }
        }
        return groupIds;
    },

    _getCleanEndpoint: function() {
        var endpoint = gs.getProperty("x_1784056_sixscape.End Point") || "";
        if (endpoint.endsWith("/")) endpoint = endpoint.slice(0, -1);
        return endpoint;
    },

    _createRestMessage: function(midServer) {
        var r = new sn_ws.RESTMessageV2();
        if (midServer && midServer.trim() !== '') {
            r.setMIDServer(midServer);
            r.setEccParameter('skip_sensor', 'true');
        }
        return r;
    },

    _getProfileSysIdByGroupId: function(groupId) {
        var gr = new GlideRecordSecure('x_1784056_sixscape_profile');
        gr.addQuery('profile_group_id', groupId);
        gr.query();
        if (gr.next()) {
            return gr.getValue('sys_id');
        }
        return null;
    },

    _fetchDevicesByOwner: function(restMessage, authToken, endpoint, groupId, profileSysId, existingDeviceIds) {
        var deviceOwnerIds = [];
        var skip = 0,
            top = 1000;

        while (true) {
            authToken = this._getValidAuthToken();
            restMessage.setHttpMethod("get");
            restMessage.setRequestHeader("Authorization", authToken);
            restMessage.setRequestHeader('User-Agent', 'snow');
            restMessage.setRequestHeader("Content-Type", "application/json");
            restMessage.setEndpoint(endpoint + "/v1/device");
            restMessage.setQueryParameter("deviceOwnerId", "eq " + groupId);
            restMessage.setQueryParameter("$skip", skip);
            restMessage.setQueryParameter("$top", top);
            restMessage.setHttpTimeout(30000);

            var response = restMessage.execute();
            if (response.haveError()) {
                this._logRestError("fetchDevicesByOwner", endpoint + "/v1/device", {
                    groupId: groupId,
                    skip: skip,
                    top: top
                }, response);
                break;
            }
            var body;
            try {
                body = JSON.parse(response.getBody());
            } catch (e) {
                this._logError("fetchDevicesByOwner", "parseBody", endpoint + "/v1/device", response.getBody(), e.message);
                break;
            }
            if (!body || !Array.isArray(body) || body.length === 0) break;

            body.forEach(function(device) {
                if (device && device.deviceId) {
                    deviceOwnerIds.push(device.deviceId);
                    this._upsertDevice(device, profileSysId, existingDeviceIds);
                }
            }.bind(this));

            if (body.length !== top) break;
            skip += top;
        }
        return deviceOwnerIds;
    },

    _upsertDevice: function(device, profileSysId, existingDeviceIds) {
        var gr = new GlideRecordSecure('x_1784056_sixscape_device');
        gr.addQuery('device_id', device.deviceId);
        gr.query();

        if (gr.hasNext()) {
            while (gr.next()) {
                gr.device_name = device.deviceName;
                gr.device_id = device.deviceId;
                gr.device_owner_id = device.deviceOwnerId;
                gr.device_status = device.status;
                gr.profile = profileSysId;
                gr.update();
            }
            var index = existingDeviceIds.indexOf(device.deviceId);
            if (index > -1) {
                existingDeviceIds.splice(index, 1);
            }
        } else {
            gr.initialize();
            gr.device_name = device.deviceName;
            gr.device_id = device.deviceId;
            gr.device_owner_id = device.deviceOwnerId;
            gr.device_status = device.status;
            gr.profile = profileSysId;
            gr.insert();
        }
    },

    _processDevicesInBatches: function(restMessage, authToken, endpoint, deviceOwnerIds, profileSysId, existingDeviceIds) {
        var batchSize = 100;
        for (var start = 0; start < deviceOwnerIds.length; start += batchSize) {
            var currentBatch = deviceOwnerIds.slice(start, start + batchSize);
            if (!currentBatch || currentBatch.length === 0) {
				this._log("Warning", "Empty batch; skipping REST call.");
                continue;
            }

            var conditions = currentBatch.map(function(id) {
                return "deviceOwnerId=eq " + id;
            });
            var filterString = "(" + conditions.join(" $or ") + ")";

            if (!filterString || filterString === "()") {
				this._log("Warning", "No condition/filter string; skipping batch.");
                continue;
            }

            var skip = 0,
                top = 1000;
            while (true) {
                authToken = this._getValidAuthToken();
                restMessage.setHttpMethod("get");
                restMessage.setRequestHeader("Authorization", authToken);
                restMessage.setRequestHeader('User-Agent', 'snow');
                restMessage.setRequestHeader("Content-Type", "application/json");
                restMessage.setEndpoint(endpoint + "/v1/device");
                restMessage.setQueryParameter("$subfilter", filterString);
                restMessage.setQueryParameter("$skip", skip);
                restMessage.setQueryParameter("$top", top);
                restMessage.setHttpTimeout(30000);

                var response = restMessage.execute();
                if (response.haveError()) {
                    this._logRestError("processDevicesInBatches", endpoint + "/v1/device", {
                        filterString: filterString,
                        skip: skip,
                        top: top
                    }, response);
                    break;
                }

                var body;
                try {
                    body = JSON.parse(response.getBody());
                } catch (e) {
                    this._logError("processDevicesInBatches", "parseBody", endpoint + "/v1/device", response.getBody(), e.message);
                    break;
                }

                if (!body || !Array.isArray(body) || body.length === 0) break;

                body.forEach(function(device) {
                    this._upsertDevice(device, profileSysId, existingDeviceIds);
                }.bind(this));

                if (body.length !== top) break;
                skip += top;
            }
        }
    },

    _deleteObsoleteDevices: function(existingDeviceIds) {
		var self = this;
        existingDeviceIds.forEach(function(deviceId) {
            var gr = new GlideRecordSecure('x_1784056_sixscape_device');
            gr.addQuery('device_id', deviceId);
            gr.query();
            while (gr.next()) {
                gr.deleteRecord();
				self._log("Info", "Deleted obsolete application: " + deviceId);
            }
        });
    },

    _updateCertificatesForDevices: function(authToken, endpoint) {
        var gr = new GlideRecordSecure('x_1784056_sixscape_device');
        gr.query();
        var midServer = gs.getProperty("x_1784056_sixscape.Mid Server Name");
        var restMessage = this._createRestMessage(midServer);

        while (gr.next()) {
            authToken = this._getValidAuthToken();
            var deviceId = gr.getValue("device_id");
            var deviceOwnerId = gr.getValue("device_owner_id");
            var subfilter = "(name=eq " + deviceId + " $or owner=eq " + deviceId + " $or owner=eq " + deviceOwnerId + ")";

            restMessage.setHttpMethod("get");
            restMessage.setRequestHeader("Authorization", authToken);
            restMessage.setRequestHeader('User-Agent', 'snow');
            restMessage.setRequestHeader("Content-Type", "application/json");
            restMessage.setEndpoint(endpoint + "/v1/certificate");
            restMessage.setQueryParameter("$subfilter", subfilter);
            restMessage.setQueryParameter("$sort", "expiryDate desc");
            restMessage.setHttpTimeout(30000);

            var response = restMessage.execute();
            if (response.haveError()) {
                this._logRestError("updateCertificatesForDevices", endpoint + "/v1/certificate", {
                    deviceId: deviceId,
                    deviceOwnerId: deviceOwnerId,
                    subfilter: subfilter
                }, response);
                continue;
            }

            var body;
            try {
                body = JSON.parse(response.getBody());
            } catch (e) {
                this._logError("updateCertificatesForDevices", "parseBody", endpoint + "/v1/certificate", response.getBody(), e.message);
                continue;
            }
            if (!body || !Array.isArray(body) || body.length === 0) continue;

            var expiryDateGDT = new GlideDateTime(body[0].expiryDate);
            gr.certificate_name = body[0].name;
            gr.certificate_status = body[0].status;
            gr.certificate_creation_time = body[0].createdDate;
            gr.serial_number = body[0].serialNumber;
            gr.expiry_date = expiryDateGDT;
            gr.update();
        }
    },

    /**
     * Log REST API error and insert to a custom table, if present.
     */
    _logRestError: function(stage, endpoint, parameters, response) {
        var responseBody = response.getBody();
        var code = response.getStatusCode();
        var message = "REST error: HTTP " + code + " - " + responseBody;
		this._log("Error", message);
        // gs.error(message);
        this._logError(stage, "rest", endpoint, JSON.stringify(parameters), responseBody);
    },

    /**
     * General error logger, logs to table if present.
     */
    _logError: function(stage, method, endpoint, params, errMsg) {
        var msg = "DeviceSync error @ " + stage + "/" + method +
            " ENDPOINT: " + endpoint +
            " PARAMS: " + params +
            " ERROR: " + errMsg;
		this._log("Error", msg);
        // gs.error(msg);
    },

    _log: function(logLevel, message) {
        var gr = new GlideRecord('x_1784056_sixscape_log');
        gr.initialize();
        gr.script = "ScheduleForDeviceSync";
        gr.log_level = logLevel;
        gr.message = message;
        gr.application = "Sixscape IDC";
        gr.insert();

        // Optionally mirror to sys logs for real-time debug
        if (logLevel == "Info") gs.info(message);
        else if (logLevel == "Warning") gs.warn(message);
        else gs.error(message);
    },

    type: 'ScheduleForDeviceSync'
};
